# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

# The coordinator writes the pending intent on its own connection, so these
# examples run on committed data.
RSpec.describe "Api::V1::Invoices::BulkDeletion#create under the timekeeping owner", type: :request, committed_data: true do
  let(:bulk_tk_company) { create(:company) }
  let(:bulk_tk_client) { create(:client, company: bulk_tk_company) }
  let(:bulk_tk_project) { create(:project, client: bulk_tk_client, billable: true) }
  let(:bulk_tk_user) { create(:user, current_workspace_id: bulk_tk_company.id) }

  before do
    create(:employment, company: bulk_tk_company, user: bulk_tk_user)
    bulk_tk_user.add_role :admin, bulk_tk_company
    sign_in bulk_tk_user
  end

  # "a mixed bulk delete (`POST /api/v1/invoices/bulk_deletion`) where one invoice has a payment: destroyed invoices commit their own operations, and the paid invoice's reservations are unchanged;"
  it "under the timekeeping owner a mixed bulk delete commits the destroyed draft's own operation and leaves the paid invoice's reservations unchanged" do
    draft_entry = create(:timesheet_entry, user: bulk_tk_user, project: bulk_tk_project, bill_status: "unbilled")
    paid_entry = create(:timesheet_entry, user: bulk_tk_user, project: bulk_tk_project, bill_status: "unbilled")
    draft = create(:invoice, company: bulk_tk_company, client: bulk_tk_client)
    create(:invoice_line_item, invoice: draft, timesheet_entry: draft_entry, rate: 100, quantity: 60)
    paid = create(:invoice, company: bulk_tk_company, client: bulk_tk_client, amount_due: 300)
    create(:invoice_line_item, invoice: paid, timesheet_entry: paid_entry, rate: 100, quantity: 60)
    create(:payment, invoice: paid, amount: 300)
    # The lines above were saved under the legacy owner, which recorded its
    # own operations. The fake's reservations below stand in for that history,
    # so only the bulk delete's operations remain to be checked.
    InvoiceOperationIntent.where(company_id: bulk_tk_company.id).delete_all
    InvoiceOperationOutboxItem.where(company_id: bulk_tk_company.id).delete_all

    TimekeepingOwnership.current.update!(owner: "timekeeping", handoff_step: nil)
    fake = TimekeepingContract::FakeTimekeeping.new
    fake.generation = TimekeepingOwnership.current.generation
    [draft_entry, paid_entry].each do |entry|
      fake.add_entry(company_id: bulk_tk_company.id, user_id: bulk_tk_user.id, project_id: bulk_tk_project.id, id: entry.id)
    end
    fake.add_reservation(entry_id: draft_entry.id, invoice_id: draft.id, state: "committed", disposition: "active")
    fake.add_reservation(entry_id: paid_entry.id, invoice_id: paid.id, state: "committed", disposition: "active")
    credential = fake.add_service(company_id: bulk_tk_company.id, name: "miru-monolith",
                                  operations: %w[prepare commit abort mark_billed])
    client = Timekeeping::ReservationClient.new(
      http: TimekeepingContract::FakeClient.new(timekeeping: fake, relay: nil),
      credential: ->(company_id:, operation:) { credential }
    )
    allow(Timekeeping::ReservationClient).to receive(:build).and_return(client)
    paid_before = fake.reservations_for(paid_entry.id)

    send_request :post, api_v1_invoices_bulk_deletion_index_path,
      params: { invoices_ids: [draft.id, paid.id] }, headers: auth_headers(bulk_tk_user)

    expect(response).to have_http_status(:unprocessable_content)
    expect(json_response["undeletable_invoice_ids"]).to eq([paid.id])

    # The destroyed draft settles its own operation.
    expect(Invoice.exists?(draft.id)).to be(false)
    expect(InvoiceOperationIntent.where(company_id: bulk_tk_company.id, invoice_id: draft.id).pluck(:state)).to eq(["committed"])
    draft_commits = InvoiceOperationOutboxItem.where(company_id: bulk_tk_company.id, invoice_id: draft.id, kind: "commit")
    expect(draft_commits.count).to eq(1)
    expect(draft_commits.first.delivered_at).to be_present
    expect(fake.reservations_for(draft_entry.id)).to eq([])
    expect(fake.entry_locked?(draft_entry.id)).to be(false)
    expect(fake.requests.count { |request| request[:path].end_with?("/reservations/prepare") && request[:body]["invoice_id"] == draft.id })
      .to eq(1)

    # The paid invoice keeps what it held, and nothing is left for recovery to act on.
    expect(Invoice.exists?(paid.id)).to be(true)
    expect(fake.reservations_for(paid_entry.id)).to eq(paid_before)
    expect(fake.entry_locked?(paid_entry.id)).to be(true)
    expect(InvoiceOperationIntent.where(company_id: bulk_tk_company.id, invoice_id: paid.id, state: %w[pending committed]))
      .to be_empty
    expect(InvoiceOperationOutboxItem.where(company_id: bulk_tk_company.id, invoice_id: paid.id, kind: "commit")).to be_empty
    expect(fake.requests.none? { |request| request[:path].end_with?("/reservations/commit") && request[:body]["invoice_id"] == paid.id })
      .to be(true)
  end
end

RSpec.describe "Api::V1::Invoices#update of a pre-boundary sent invoice under the timekeeping owner", type: :request, committed_data: true do
  let(:pre_tk_company) { create(:company) }
  let(:pre_tk_client) { create(:client, company: pre_tk_company) }
  let(:pre_tk_project) { create(:project, client: pre_tk_client, billable: true) }
  let(:pre_tk_user) { create(:user, current_workspace_id: pre_tk_company.id) }

  before do
    create(:employment, company: pre_tk_company, user: pre_tk_user)
    pre_tk_user.add_role :admin, pre_tk_company
    sign_in pre_tk_user
  end

  def pre_tk_patch(invoice, line_items)
    send_request :patch, api_v1_invoice_path(invoice), params: {
      invoice: {
        client_id: pre_tk_client.id, invoice_number: invoice.invoice_number,
        issue_date: invoice.issue_date.iso8601, due_date: invoice.due_date.iso8601,
        status: "sent", currency: pre_tk_company.base_currency, invoice_line_items_attributes: line_items
      }
    }, headers: auth_headers(pre_tk_user)
  end

  # "an existing reservation with no intent: a line is removed from a sent invoice, then an entry is added in a separate transaction, and the old entry stays reserved;"
  it "under the timekeeping owner a sent invoice saved before the boundary keeps a removed line's entry reserved after a later addition" do
    removed_entry = create(:timesheet_entry, user: pre_tk_user, project: pre_tk_project, bill_status: "unbilled")
    kept_entry = create(:timesheet_entry, user: pre_tk_user, project: pre_tk_project, bill_status: "unbilled")
    added_entry = create(:timesheet_entry, user: pre_tk_user, project: pre_tk_project, bill_status: "unbilled")
    invoice = create(:invoice, company: pre_tk_company, client: pre_tk_client, invoice_number: "INV-PRE-TK-1")
    removed_line = create(:invoice_line_item, invoice:, timesheet_entry: removed_entry, rate: 100, quantity: 60)
    create(:invoice_line_item, invoice:, timesheet_entry: kept_entry, rate: 100, quantity: 60)
    invoice.update_columns(status: "sent")
    # An invoice saved before the boundary has no holding, intent or outbox row.
    InvoiceEntryHolding.where(invoice_id: invoice.id).delete_all
    InvoiceOperationOutboxItem.where(invoice_id: invoice.id).delete_all
    InvoiceOperationIntent.where(invoice_id: invoice.id).delete_all

    TimekeepingOwnership.current.update!(owner: "timekeeping", handoff_step: nil)
    fake = TimekeepingContract::FakeTimekeeping.new
    fake.generation = TimekeepingOwnership.current.generation
    [removed_entry, kept_entry, added_entry].each do |entry|
      fake.add_entry(company_id: pre_tk_company.id, user_id: pre_tk_user.id, project_id: pre_tk_project.id, id: entry.id)
    end
    fake.add_reservation(entry_id: removed_entry.id, invoice_id: invoice.id, state: "committed", disposition: "active")
    fake.add_reservation(entry_id: kept_entry.id, invoice_id: invoice.id, state: "committed", disposition: "active")
    credential = fake.add_service(company_id: pre_tk_company.id, name: "miru-monolith",
                                  operations: %w[prepare commit abort mark_billed])
    client = Timekeeping::ReservationClient.new(
      http: TimekeepingContract::FakeClient.new(timekeeping: fake, relay: nil),
      credential: ->(company_id:, operation:) { credential }
    )
    allow(Timekeeping::ReservationClient).to receive(:build).and_return(client)

    pre_tk_patch(invoice, [{ id: removed_line.id, name: removed_line.name, description: removed_line.description,
                             date: removed_line.date.iso8601, rate: 100, quantity: 60, _destroy: true }])
    expect(response).to have_http_status(:ok)

    pre_tk_patch(invoice.reload, [{ name: "Added", description: "added", date: Date.current.iso8601, rate: 100,
                                    quantity: 60, timesheet_entry_id: added_entry.id }])
    expect(response).to have_http_status(:ok)

    expect(invoice.reload.invoice_line_items.pluck(:timesheet_entry_id)).to contain_exactly(kept_entry.id, added_entry.id)
    expect(fake.entry_locked?(removed_entry.id)).to be(true)
    expect(fake.reservations_for(removed_entry.id)).to eq([{ "invoice_id" => invoice.id, "state" => "committed" }])
    expect(fake.entry_locked?(kept_entry.id)).to be(true)
  end
end

RSpec.describe "Api::V1::Invoices#update under the timekeeping owner", type: :request, committed_data: true do
  # "the fake applies prepare but the answer is dropped: the save fails, and after abort each entry's reservation state equals its state before the save;"
  it "a nested update whose prepare answer is lost fails and leaves the entry as unreserved on Timekeeping as before the save" do
    company = create(:company)
    client = create(:client, company:)
    project = create(:project, client:, billable: true)
    user = create(:user, current_workspace_id: company.id)
    create(:employment, company:, user:)
    user.add_role :admin, company
    row = create(:timesheet_entry, user:, project:, bill_status: "unbilled")
    invoice = create(:invoice, company:, client:, invoice_number: "TK-LOST-PREPARE")
    TimekeepingOwnership.current.update!(owner: "timekeeping", handoff_step: nil)

    fake = TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key)
    fake.generation = TimekeepingOwnership.current.generation
    fake.add_entry(company_id: company.id, user_id: user.id, project_id: project.id, id: row.id)
    before_save = [fake.reservations_for(row.id), fake.entry_locked?(row.id)]
    fake_client = TimekeepingContract::FakeClient.new(timekeeping: fake, relay: nil)
    # Timekeeping applies the first prepare, then its answer is lost on the way back.
    dropping_http = Object.new
    dropped = false
    dropping_http.define_singleton_method(:call) do |method, path, headers: {}, body: nil|
      answer = fake_client.call(method, path, headers:, body:)
      if path.end_with?("/reservations/prepare") && !dropped
        dropped = true
        raise Timekeeping::ReservationClient::TransportError, "Timekeeping prepare failed: Net::ReadTimeout"
      end
      answer
    end
    credential = lambda do |company_id:, operation:|
      Timekeeping::ServiceToken.mint(company_id:, operations: [operation], private_key: timekeeping_key_pair)
    end
    allow(Timekeeping::ReservationClient).to receive(:build)
      .and_return(Timekeeping::ReservationClient.new(http: dropping_http, credential:))
    sign_in user

    send_request :patch, api_v1_invoice_path(invoice), params: {
      invoice: {
        client_id: client.id, invoice_number: "TK-LOST-PREPARE", issue_date: invoice.issue_date.iso8601,
        due_date: invoice.due_date.iso8601, status: "draft", currency: company.base_currency,
        invoice_line_items_attributes: [
          { name: "Work", description: "Work", date: row.work_date.iso8601, rate: 100, quantity: 60,
            timesheet_entry_id: row.id }
        ]
      }
    }

    expect(response).not_to have_http_status(:ok)
    expect(dropped).to be(true)
    expect(InvoiceLineItem.where(invoice_id: invoice.id, timesheet_entry_id: row.id)).to be_empty
    expect(InvoiceOperationIntent.where(company_id: company.id, invoice_id: invoice.id).pluck(:state)).to eq(["failed"])
    abort_row = InvoiceOperationOutboxItem.find_by!(company_id: company.id, invoice_id: invoice.id, kind: "abort")
    expect(abort_row.delivered_at).to be_present
    expect([fake.reservations_for(row.id), fake.entry_locked?(row.id)]).to eq(before_save)
  end
end
